import pennylane as qp
from pennylane import numpy as np
np.random.seed(0)
dev = qp.device('default.qubit', wires=1)
n_layers = 4

def S(x):
    qp.RX(x, wires=0)

def W(theta):
    qp.Rot(theta[0], theta[1], theta[2], wires=0)

@qp.qnode(dev, diff_method='backprop')
def model(params, x):
    S(x)
    for i in range(n_layers):
        W(params[i])
    W(params[n_layers])
    return qp.expval(qp.PauliZ(0))

def cost(params, X, Y):
    preds = np.stack([model(params, x) for x in X])
    return np.mean((Y - preds) ** 2)
X = np.linspace(-3.0, 3.0, 20, requires_grad=False)
Y = np.array([0.3 * np.sin(2 * x) + 0.3 * np.cos(3 * x) for x in X], requires_grad=False)
params = 0.1 * np.random.randn(n_layers + 1, 3, requires_grad=True)
opt = qp.AdamOptimizer(0.3)
for _ in range(80):
    params, _, _ = opt.step(cost, params, X, Y)
final_loss = float(cost(params, X, Y))

