import pennylane as qml
from pennylane import numpy as np
np.random.seed(0)
graph = [(0, 1), (1, 2), (2, 3), (3, 4), (4, 0), (1, 3)]
n_wires = 5
depth = 2
dev = qml.device('default.qubit', wires=n_wires)

def cost_layer(gamma):
    for u, v in graph:
        qml.CNOT(wires=[u, v])
        qml.RZ(gamma, wires=v)
        qml.CNOT(wires=[u, v])

def mixer_layer(beta):
    for w in range(n_wires):
        qml.RX(2 * beta, wires=w)

@qml.qnode(dev, diff_method='backprop')
def cost_function(params):
    gammas, betas = (params[0], params[1])
    for w in range(n_wires):
        qml.Hadamard(wires=w)
    for layer in range(depth):
        cost_layer(gammas[layer])
        mixer_layer(betas[layer])
    return qml.expval(qml.sum(*[qml.X(u) @ qml.X(v) for u, v in graph]))

def objective(params):
    return cost_function(params)
params = 0.5 * np.ones((2, depth), requires_grad=True)
opt = qml.AdagradOptimizer(stepsize=0.5)
for _ in range(70):
    params = opt.step(objective, params)

@qml.qnode(dev, diff_method='backprop')
def _verify(params):
    for w in range(n_wires):
        qml.Hadamard(wires=w)
    for layer in range(depth):
        cost_layer(params[0][layer])
        mixer_layer(params[1][layer])
    return qml.expval(qml.sum(*[qml.Z(u) @ qml.Z(v) for u, v in graph]))
cut_value = 0.5 * (len(graph) - float(_verify(params)))

