import pennylane as qp
from pennylane import numpy as np
n_qubits = 3
tot_qubits = n_qubits + 1
ancilla_idx = n_qubits
steps = 30
eta = 0.8
q_delta = 0.001
np.random.seed(0)
c = np.array([1.0, 0.7, 0.7])

def U_b():
    for idx in range(n_qubits):
        qp.Hadamard(wires=idx)

def CA(idx):
    if idx == 0:
        pass
    elif idx == 1:
        qp.CNOT(wires=[ancilla_idx, 0])
        qp.CZ(wires=[ancilla_idx, 1])
    elif idx == 2:
        qp.CNOT(wires=[ancilla_idx, 0])

def variational_block(weights):
    for idx, element in enumerate(weights):
        qp.RY(element, wires=idx)
dev_mu = qp.device('default.qubit', wires=tot_qubits)

@qp.qnode(dev_mu, interface='autograd')
def local_hadamard_test(weights, l=None, lp=None, j=None, part=None):
    qp.Hadamard(wires=ancilla_idx)
    if part == 'Im' or part == 'im':
        qp.PhaseShift(-np.pi / 2, wires=ancilla_idx)
    variational_block(weights)
    CA(l)
    U_b()
    if j != -1:
        qp.CZ(wires=[ancilla_idx, j])
    U_b()
    CA(lp)
    qp.Hadamard(wires=ancilla_idx)
    return qp.expval(qp.PauliZ(wires=ancilla_idx))

def mu(weights, l=None, lp=None, j=None):
    mu_real = local_hadamard_test(weights, l=l, lp=lp, j=j, part='Re')
    mu_imag = local_hadamard_test(weights, l=l, lp=lp, j=j, part='Im')
    return mu_real + 1j * mu_imag

def psi_norm(weights):
    norm = 0.0
    for l in range(len(c)):
        for lp in range(len(c)):
            norm = norm + c[l] * np.conj(c[lp]) * mu(weights, l, lp, -1)
    return abs(norm)

def cost_loc(weights):
    mu_sum = 0.0
    for l in range(len(c)):
        for lp in range(len(c)):
            for j in range(n_qubits):
                mu_sum = mu_sum + c[l] * np.conj(c[lp]) * mu(weights, l, lp, j)
    mu_sum = abs(mu_sum)
    return 0.5 - 0.5 * mu_sum / (n_qubits * psi_norm(weights))
w = q_delta * np.random.randn(n_qubits, requires_grad=True)
opt = qp.GradientDescentOptimizer(eta)
cost_history = []
for it in range(steps):
    w, cost = opt.step_and_cost(cost_loc, w)
    cost_history.append(cost)
final_cost = cost_history[-1]

